import type { BlogArticleFaq } from '../../../types/blog';

export const BODY: string = "\n<p>تقسيم صورة عمل قصير: ترفع صورة وتختار كيف تقسمها وتراجع خطوط القطع وتنزّل القطع. يمر هذا الدليل بكل خطوة بالترتيب، من أول رفع إلى المربعات المنتهية.</p>\n<p>قبل أن تبدأ تحتاج شيئًا واحدًا فقط: الصورة التي تريد تقسيمها. صورة كبيرة عالية الدقة تعطي أفضل المربعات، لأن كل مربع يُقص بالحجم الأصلي الكامل. وصورة صغيرة تعطي مربعات صغيرة ناعمة.</p>\n<p>يقوم <a href=\"/ar/taqsim-as-suwar/\">مقسم الصور</a> بالعمل في متصفحك. لا شيء يُرفع إلى خادم ولا حساب، والمربعات تُنزّل مجانًا. اتبع الخطوات أدناه وستكون لديك صورة مقسمة في دقائق معدودة.</p>\n<h2 id=\"step-1-upload-your-image\">الخطوة 1: ارفع صورتك</h2>\n<p>افتح المقسم واسحب صورتك إلى منطقة الرفع، أو انقر لاختيار ملف من جهازك. ويمكنك أيضًا لصق صورة مباشرة من الحافظة بـCtrl+V، وهو مفيد للقطات الشاشة.</p>\n<p>تقبل الأداة ملفات JPG وPNG وWebP وHEIC وGIF وBMP وSVG حتى 20 MB: معظم الصور واللقطات أقل بكثير من ذلك الحد. وصورة HEIC من iPhone تُرفع وتُقسم دون مشاكل. وبمجرد تحميل الصورة، يُولد تلقائيًا تقسيم أولي 3 في 3: سترى الشبكة وخطوط القطع المرقمة في المعاينة فورًا، ما يمنحك نقطة بداية.</p>\n<p>وإذا رفعت الملف الخطأ، استبدله دون فقدان ضبطك: تتيح لك الأداة تغيير الصورة مع إبقاء وضع التقسيم وحجم الشبكة، فالخطأ يكلف ثوانٍ لا إعادة بناء.</p>\n<h2 id=\"step-2-choose-a-split-mode\">الخطوة 2: اختر وضع تقسيم</h2>\n<p>اختر أحد الأوضاع الثلاثة: شبكة أو أشرطة أفقية أو أشرطة عمودية. الشبكة تقسم الصورة إلى صفوف وأعمدة، وهي الوضع لشبكات إنستغرام والألغاز والملصقات.</p>\n<p>الأشرطة الأفقية تقطع الصورة إلى صفوف مكدسة: اختر هذا الوضع للقطات الطويلة والرسوم البيانية الطويلة وكل ما يُقرأ من أعلى إلى أسفل. وكل شريط صورة عريضة وقصيرة تعرض جزءًا من المحتوى. والأشرطة العمودية تقطع الصورة إلى أعمدة جنبًا إلى جنب: اختر هذا الوضع للبانوراما العريضة واللافتات، حيث يستمر كل شريط المشهد إلى اليمين. وبانوراما مقسمة إلى أشرطة عمودية تُقرأ كمشهد واحد يتدفق.</p>\n<p>وإذا لم تعرف أي وضع يناسب أفضل، ابدأ بالشبكة: إنه أكثر وضع مرونة، وتستطيع التبديل إلى وضع أشرطة في أي وقت دون فقدان الصورة. وتتحدث المعاينة عند التبديل.</p>\n<h2 id=\"step-3-set-rows-and-columns\">الخطوة 3: حدد الصفوف والأعمدة</h2>\n<p>في وضع الشبكة، حدد عدد الصفوف والأعمدة: ثلاثة صفوف وثلاثة أعمدة تعطي شبكة إنستغرام الكلاسيكية ذات المربعات التسعة. واثنان في اثنين يعطي تقسيمًا بسيطًا بأربعة مربعات.</p>\n<p>فكر في حجم المربعات قبل الاختيار: صورة 3000 بكسل مقسمة 3 في 3 تعطي مربعات 1000 بكسل، كبيرة بما يكفي للنشر في أي مكان. ونفس الصورة مقسمة 5 في 5 تعطي مربعات 600 بكسل، ما زالت جيدة للخلاصات لكنها أصغر. وفي أوضاع الأشرطة، حدد عدد الأشرطة: أربعة أشرطة أفقية للقطة طويلة وثلاثة أشرطة عمودية لبانوراما وشريطان لتقسيم بسيط. والأشرطة أعرض من مربعات الشبكة، فكل شريط يحمل محتوى أكثر.</p>\n<p>غيّر الأرقام بحرية وراقب المعاينة: تتحرك خطوط القطع وأنت تضبط، ويتحدث عدد المربعات. ولا يكلف التجريب شيئًا، لأن لا شيء يُنزّل حتى تطلب ذلك.</p>\n<h2 id=\"step-4-use-a-preset\">الخطوة 4: استخدم إعدادًا مسبقًا</h2>\n<p>الإعدادات المسبقة ضبط بنقرة واحدة للتقسيمات الشائعة: إعداد شبكة إنستغرام 3 في 3 هو ما يحتاجه معظم الناس، وتشمل الأداة إعدادات أخرى لأحجام وشبكات شائعة.</p>\n<p>الإعداد المسبق نقطة بداية: بعد لمسه، اضبط الأرقام إذا احتاجت صورتك أو خطتك شكلًا آخر. ويوفر عليك الإعداد المسبق الكتابة، وأنت تحافظ على التحكم الكامل في التقسيم. واستخدم الإعدادات المسبقة عندما تقسم صورًا كثيرًا: مدير تواصل اجتماعي يبني شبكة كل أسبوع يستطيع لمس نفس الإعداد المسبق في كل مرة والحصول على نفس الأحجام.</p>\n<p>وإذا لم يطابق أي إعداد مسبق عملك، حدد الصفوف والأعمدة يدويًا: شبكة 4 في 5 لملصق أو شريط 1 في 6 للافتة تقسيمان صالحان، والضوابط تتيح لك أي مزيج.</p>\n<h2 id=\"step-5-inspect-the-cut-lines\">الخطوة 5: راجع خطوط القطع</h2>\n<p>انظر إلى المعاينة وجد خطوط القطع المرقمة: تُظهر بالضبط أين يبدأ كل مربع وينتهي، والأرقام تشير إلى موضع كل مربع في الشبكة، من اليسار إلى اليمين ومن أعلى إلى أسفل.</p>\n<p>راجع إن مر أي خط قطع عبر وجه أو سطر نص أو تفصيل مهم: وجه مقسوم إلى مربعين يبدو كخطأ، ونص مقطوع إلى نصفين غير مقروء في المربعين. ولصورة مصدر غير مربعة، راجع أشكال المربعات: صورة عريضة مقسمة 3 في 3 تعطي مربعات عريضة، لا مربعة، وقد لا تنفع تلك المربعات لشبكة مربعة.</p>\n<p>اضبط الصفوف والأعمدة، أو قص الصورة المصدر إلى مربع أولًا، لتخرج المربعات بالشكل الذي تحتاجه. وقرّب على المعاينة إذا كانت الصورة بها تفاصيل كثيرة: خطوط قطع تبدو جيدة بحجم صغير قد تخفي مشكلة في منطقة مزدحمة من الصورة. وبضع ثوانٍ من المراجعة توفر إعادة نشر.</p>\n<h2 id=\"step-6-choose-the-tile-format\">الخطوة 6: اختر صيغة المربعات</h2>\n<p>اختر الصيغة للمربعات: يناسب JPG الصور ويعطي ملفات صغيرة، وهو ما تريده للمنشورات الاجتماعية واستخدام الويب. ويناسب PNG الرسوم والنص وكل ما له حواف حادة، لأنه يحافظ على كل بكسل بدقة.</p>\n<p>يظهر ضبط جودة المربعات لمربعات JPG: يتحكم في ضغط مخرجات JPG، فقيمة عالية تحافظ على تفاصيل أكثر وقيمة منخفضة تعطي ملفات أصغر. ومربعات PNG ليس لها ضبط جودة، لأن PNG دون فقدان. ولصور PNG الشفافة، اختر PNG كصيغة مربعات: JPG ليس له شفافية، فمربع شفاف مصدّر كـJPG يكسب خلفية صلبة. والشفافية تنجو فقط مع PNG.</p>\n<p>طابق الصيغة مع الوجهة: المنشورات الاجتماعية والطباعة تعمل جيدًا مع JPG، بينما أوراق sprites والأيقونات وموارد التصميم تحتاج PNG. وعند الشك، صدّر JPG للصور وPNG للرسوم.</p>\n<h2 id=\"step-7-download-the-tiles\">الخطوة 7: نزّل المربعات</h2>\n<p>نزّل المربعات كـZIP للحصول عليها كلها دفعة واحدة: يحتوي ZIP كل مربع كملف مرقم، بترتيب القراءة من الزاوية العلوية اليسرى. وفك ضغطه وستكون المجموعة جاهزة للنشر أو الطباعة.</p>\n<p>ويمكنك أيضًا تنزيل مربعات واحدًا واحدًا إذا احتجت بعضها فقط: مربع واحد لصورة ملف شخصي أو شريط واحد للافتة لا يحتاج المجموعة كلها، والتنزيل الفردي يوفر وقتًا. وراجع أبعاد المربعات بعد التنزيل: افتح مربعًا وتأكد من أن له الحجم الذي توقعته، خصوصًا لأعمال الطباعة أو أوراق sprites حيث تكون البكسلات الدقيقة مهمة.</p>\n<p>احتفظ بـZIP كنسخة احتياطية حتى تستخدم المربعات: إذا فُقد مربع أو فشل نشر، يستعيد ZIP المجموعة دون جولة تقسيم أخرى. واحذفه فقط عندما ينتهي العمل.</p>\n<h2 id=\"step-8-name-and-organize\">الخطوة 8: سمِّ ونظّم</h2>\n<p>المربعات المنزّلة مرقمة، لكن أسماء الملفات عامة: غيّرها إذا احتاج العمل أسماء ذات معنى، مثل rompecabezas-fila-1 أو poster-mosaico-a1. والأسماء الواضحة تمنع الخلط عندما تكون هناك مجموعات عدة.</p>\n<p>أبقِ كل تقسيم في مجلده الخاص: مجلد باسم العمل، مع المربعات بداخله بالترتيب، أسهل إدارة من مجلد تنزيلات مليء بملفات مرقمة من أعمال مختلفة. ولشبكات إنستغرام، أبقِ المربعات بترتيب النشر، لا بترتيب الشبكة: تعرض المنصة أحدث منشور أولًا، فيجب نشر المربعات بترتيب عكسي، من المربع الأخير إلى الأول.</p>\n<p>دوّن ضبط التقسيم في مكان ما إذا كنت ستكرر العمل: شبكة 3 في 3 من صورة مربعة سهلة التذكر، لكن تقسيمًا مخصصًا 4 في 5 بجودة محددة يستحق ملاحظة.</p>\n<h2 id=\"step-9-check-the-tiles\">الخطوة 9: راجع المربعات</h2>\n<p>افتح بعض المربعات بالحجم الكامل وانظر إلى الحواف: يجب أن يُظهر كل مربع قطعًا نظيفًا، دون شريط من المربع المجاور ولا شريط مفقود عند الحد. وتقسيم نظيف غير مرئي عند إعادة تجميع المربعات.</p>\n<p>راجع خصوصًا المربعين الأول والأخير: مربعات الحافة تكشف مشاكل تقسيم غير متساوٍ، حيث لم تنقسم أبعاد الصورة بالتساوي وكانت مربعات الحافة أكبر ببكسل أو اثنين. وانظر إلى المربعات معًا إذا كان العمل شبكة أو لغزًا: ضعها بالترتيب على الشاشة، أو جمّعها في كولاج، وتأكد من أن الصورة تُعاد بناؤها جيدًا. ومربع خارج مكانه يفسد الصورة كاملة.</p>\n<p>وإذا بدا مربع سيئًا، لا تصلحه يدويًا: عُد إلى المقسم واضبط الشبكة أو صورة المصدر وقسّم مجددًا. وتقسيم جديد يبقي كل مربع متسقًا، بينما إصلاح يدوي يخلق مربعًا لا يطابق بقية المجموعة.</p>\n<h2 id=\"step-10-reuse-the-setup\">الخطوة 10: أعد استخدام الضبط</h2>\n<p>احفظ الضبط الذي نجح: حجم الشبكة والوضع وصيغة المربعات هي الأرقام الثلاثة التي تحدد تقسيمًا، وإعادة استخدامها تبقي سلسلة تقسيمات متسقة.</p>\n<p>قسّم صورة جديدة بنفس الضبط برفعها وتطبيق نفس الأرقام: الأداة لا تتذكر شيئًا بين الزيارات، فالملاحظة التي كتبتها في الخطوة 8 هي السجل. واحفظ تلك الملاحظة مع ملفات المشروع. وعندما يتغير شكل صورة المصدر، قد يحتاج الضبط تعديلات: صورة مربعة وعريضة مقسمتان 3 في 3 تعطيان مربعات بأشكال مختلفة، فراجع المعاينة قبل التنزيل.</p>\n<p>أنشئ مكتبة صغيرة لإعدادات التقسيم المسبقة في ملاحظاتك: إنستغرام 3 في 3 وملصق 4 في 5 ولقطة 4 أشرطة وأي تقسيم آخر تستخدمه كثيرًا. وقائمة مكتوبة تعني أن التقسيم التالي يبدأ بضبط معروف.</p>\n<h2 id=\"fixing-uneven-splits\">كيف تصلح تقسيمات غير متساوية</h2>\n<p>يحدث تقسيم غير متساوٍ عندما لا تنقسم أبعاد الصورة بالتساوي بين الصفوف أو الأعمدة: صورة 1000 بكسل مقسمة إلى 3 أعمدة تعطي مربعات 333 و333 و334 بكسلًا.</p>\n<p>فرق بكسل واحد غير مرئي في كل استخدام تقريبًا: المنشورات الاجتماعية والدوارات وتصاميم الطباعة تتسامح معه دون أي درز مرئي. ولا تطارد تقسيمًا مثاليًا بالبكسل عندما لا يهم. ولأعمال البكسل المثالي مثل أوراق sprites، قص صورة المصدر أولًا: قص الصورة إلى أبعاد تنقسم بالتساوي بين الشبكة، ثم قسّم. ومربع بلا بقايا يعطي مربعات متطابقة تمامًا.</p>\n<p>راجع أبعاد المربعات في التنزيل إذا همّت الدقة: افتح المربعات وتأكد من الأحجام قبل استخدامها في محرك لعبة أو تصميم طباعة، حيث فرق بكسل واحد قد يكسر المحاذاة.</p>\n<h2 id=\"splitting-for-a-specific-platform\">تقسيم لمنصة محددة</h2>\n<p>كل منصة لها توقعاتها الخاصة للمربعات: شبكات إنستغرام تحتاج مربعات مربعة، فيجب أن تكون صورة المصدر مربعة وأن تكون الشبكة 3 في 3.</p>\n<p>تحتاج الطباعة مربعات تطابق حجم الورق: ملصق مقسم لصفحات A4 يحتاج مربعات بنسب A4، فحدد الشبكة من أبعاد الورق لا من الصورة. وتحتاج الدوارات مربعات تُقرأ وحدها: بانوراما مقسمة إلى أشرطة عمودية تعطي أشرطة يُظهر كل منها جزءًا من المشهد، ويجب أن يكون كل جزء مثيرًا بما يكفي للوقوف وحده.</p>\n<p>وعندما تغيّر منصة تصميمها، قد يحتاج التقسيم أيضًا إلى تغيير: غيّرت إنستغرام شكل شبكة ملفها الشخصي من قبل، وشبكة مبنية للشكل القديم قد لا تناسب الشكل الجديد. وراجع قواعد المنصة الحالية قبل بناء شبكة جديدة.</p>\n<h2 id=\"quick-reference\">مرجع سريع: قائمة تحقق للتقسيم</h2>\n<p>ارفع صورة مصدر كبيرة واختر شبكة أو وضع أشرطة وحدد الصفوف والأعمدة أو المس إعدادًا مسبقًا، وراجع خطوط القطع المرقمة للوجوه والنص. واختر JPG للصور وPNG للرسوم.</p>\n<p>نزّل ZIP وأبقِ المربعات بالترتيب وانشر مربعات الشبكة بترتيب عكسي. وإذا خرج قطع سيئًا أو خرجت المربعات غير متساوية، اضبط الشبكة أو قص صورة المصدر وقسّم مجددًا.</p>\n<p>للدليل الكامل، اقرأ <a href=\"/ar/blog/dalil-taqsim-as-suwar/\">الدليل الكامل لمقسم الصور</a>، ولشبكة إنستغرام بالتفصيل اقرأ <a href=\"/ar/blog/taqsim-as-suwar-li-shabakat-instagram/\">تقسيم الصور لشبكات إنستغرام وألغازها</a>. وقسّم صورتك من <a href=\"/ar/taqsim-as-suwar/\">مقسم الصور</a>.</p>\n";

export const FAQS: BlogArticleFaq[] = [{"question":"كيف أعرف كم صفًا وعمودًا أختار؟","answer":"طابق العدد مع العمل: 3 في 3 لشبكة إنستغرام و2 في 2 لتقسيم بسيط، وعدد أشرطة بقدر الصفحات أو الشرائح التي لديك للقطة طويلة. ومربعات أقل تعني مربعات أكبر وأوضح."},{"question":"ماذا يحدث إذا لم تنقسم صورتي بالتساوي؟","answer":"تخرج مربعات الحافة أكبر ببكسل أو اثنين من البقية، لأن البكسلات المتبقية يجب أن تذهب إلى مكان ما. وفرق بكسل واحد غير مرئي في الاستخدام العادي. ولأعمال البكسل المثالي، قص المصدر إلى أبعاد تنقسم بالتساوي أولًا."},{"question":"هل يمكنني تقسيم لقطة شاشة إلى صفحات قابلة للطباعة؟","answer":"نعم، استخدم الأشرطة الأفقية وحدد عدد الأشرطة حسب عدد الصفحات التي تريدها: كل شريط يُطبع على صفحته الخاصة، والأشرطة معًا تحتوي اللقطة كلها. واختر العدد لتكون كل صفحة مقروءة."},{"question":"كيف أعيد تجميع المربعات؟","answer":"ضعها بترتيب مرقم، من اليسار إلى اليمين ومن أعلى إلى أسفل، بدءًا بالمربع واحد في الزاوية العلوية اليسرى. ولشبكة إنستغرام، انشرها بترتيب عكسي، من المربع الأخير إلى الأول."},{"question":"أي صيغة يجب أن أختار للمربعات؟","answer":"اختر JPG للصور الفوتوغرافية وأي استخدام تكون فيه الملفات الصغيرة مهمة، مثل المنشورات الاجتماعية. واختر PNG للرسوم والنص والصور الشفافة، لأن PNG يحافظ على كل بكسل بدقة ويبقي الشفافية."},{"question":"هل يمكنني تقسيم صورة على هاتفي؟","answer":"نعم، يعمل المقسم في متصفح الهواتف والأجهزة اللوحية، إضافة إلى سطح المكتب: ارفع من معرض صورك وحدد الشبكة ونزّل ZIP. وصورة مصدر كبيرة تعمل أفضل، فاستخدم أعلى دقة لديك."}];
